public class Main {
    static class FirstUnique {
        Deque<Integer> queue = new ArrayDeque<>();
        Map<Integer, Integer> count = new HashMap<>();

        FirstUnique(int[] nums) {
            for (int n : nums) add(n);
        }

        void add(int value) {
            count.merge(value, 1, Integer::sum);
            if (count.get(value) == 1) {
                queue.addLast(value);
            }
        }

        int showFirstUnique() {
            while (!queue.isEmpty() && count.get(queue.peekFirst()) > 1) {
                queue.pollFirst();
            }
            return queue.isEmpty() ? -1 : queue.peekFirst();
        }
    }

    public static void main(String[] args) {
        FirstUnique fu = new FirstUnique(new int[]{2, 3, 5});
